from produire import produire
from format_lecon import paras,table,steps
parts=[
('Le {syndrome d’apnées-hypopnées obstructives du sommeil} associe une obstruction répétée pendant le sommeil et un contexte clinique compatible. Le ronflement est un signe d’appel fréquent. Sa présence seule ne pose pas le diagnostic.',paras('Pendant les épisodes obstructifs, les efforts respiratoires persistent malgré la réduction ou l’arrêt du débit. La fragmentation du sommeil et les désaturations peuvent produire des symptômes diurnes.', 'Les apnées centrales et l’hypoventilation correspondent à d’autres mécanismes, parfois associés. Leur identification change les explorations et le traitement ; un appareil de pression positive standard ne répond pas à toutes les situations.')),
('Le {risque augmente avec l’obésité, l’âge et certaines anatomies}. Une personne mince peut aussi être atteinte. Les maladies cardiovasculaires et métaboliques orientent la recherche.',paras('La recommandation suisse cite une cohorte lausannoise d’âge moyen à avancé. Avec un IAH supérieur à 5 par heure et un score d’Epworth supérieur à 10, la fréquence était de 12,5 % chez les hommes et 5,9 % chez les femmes. Ces données ne décrivent ni tous les ronfleurs ni toutes les apnées sans somnolence.', 'Rechercher notamment hypertension résistante, fibrillation auriculaire, insuffisance cardiaque, diabète, antécédent vasculaire, hypothyroïdie ou acromégalie selon les signes. Ces associations ne signifient pas que toute complication sera prévenue par la ventilation.')),
('La {collapsibilité pharyngée explique les événements obstructifs}. Le sommeil réduit le tonus dilatateur des voies aériennes. Les tissus mous et la structure craniofaciale modifient l’espace disponible.',paras('Le rétrécissement peut intéresser plusieurs étages. L’effort inspiratoire augmente, puis un micro-éveil peut rouvrir le pharynx : le cycle se répète et fragmente le sommeil.', 'L’hypoxémie intermittente et les variations d’activité autonome participent aux conséquences générales. Un indice horaire identique peut recouvrir des événements de durée et de profondeur très différentes.')),
('Le {risque immédiat concerne vigilance et respiration}. Un endormissement au volant impose l’arrêt de la conduite et une évaluation rapide. Une décompensation respiratoire exige une prise en charge urgente.',paras('Prioriser aussi professions de sécurité, grossesse, maladie cardiovasculaire instable et préparation d’une chirurgie majeure. Transmettre clairement les symptômes au service du sommeil.', 'Chez une personne obèse avec hypoxémie à l’éveil, céphalées et signes de rétention de dioxyde de carbone, rechercher un syndrome obésité-hypoventilation. Ne pas considérer une saturation mesurée seule comme une étude complète du sommeil.')),
('L’{anamnèse explore nuits et fonctionnement diurne}. Demander pauses observées, étouffements, nycturie et réveils non réparateurs. Quantifier l’impact sur les activités et la sécurité.',paras('Le partenaire peut apporter des informations utiles avec l’accord du patient. Préciser horaires, durée du sommeil, médicaments, alcool et autres causes de somnolence.', 'Epworth mesure une plainte de somnolence et les scores STOP-Bang ou NoSAS estiment un risque. Aucun score normal ne ferme le dossier si les signes sont évocateurs.')),
('L’{examen associe anthropométrie, voies aériennes et état général}. Noter pression artérielle et morphologie craniofaciale. Examiner nez, langue, palais, amygdales et dentition.',paras('Une rétrognathie, une macroglossie ou une obstruction nasale peuvent contribuer sans être une explication unique. L’examen diurne ne reproduit pas toutes les conditions du sommeil.', 'Rechercher signes cardiaques, pulmonaires et endocriniens selon le contexte. Les symptômes et les données du sommeil priment sur l’impression que la gorge paraît suffisamment large.')),
('L’{approche syndromique distingue plusieurs causes de fatigue}. Les apnées peuvent coexister avec un manque de sommeil ou une insomnie. Le traitement doit vérifier ce qui explique les symptômes.',table(['Présentation','Hypothèse à examiner'],[['Pauses avec effort, ronflement, étouffement.','Obstruction nocturne.'],['Insuffisance cardiaque ou opioïdes, respiration périodique.','Événements centraux possibles.'],['Obésité et hypercapnie à l’éveil.','Hypoventilation associée.'],['Somnolence persistante malgré contrôle respiratoire.','Sommeil insuffisant, médicaments, autre trouble du sommeil ou maladie générale.'] ])),
('Le {diagnostic demande un enregistrement interprété avec la clinique}. La polygraphie ou la polysomnographie objective les événements. La sévérité ne se résume pas à leur nombre.',paras('Chez l’adulte, NICE définit une apnée comme une pause d’au moins dix secondes. Ses classes fondées sur l’IAH sont : légère de 5 à moins de 15 par heure, modérée de 15 à moins de 30, sévère dès 30. Ces seuils ne remplacent pas l’évaluation clinique et ne sont pas ceux de l’enfant. La recommandation suisse demande une lecture manuelle par un praticien qualifié. Le compte rendu doit préciser type d’enregistrement, qualité et règles de cotation, car le temps enregistré et le temps réellement dormi peuvent différer.', 'L’indication thérapeutique suisse retient les formes sévères. Elle inclut les formes modérées avec symptômes ou facteurs cardiovasculaires. Pour une forme légère, elle requiert une somnolence significative après recherche d’autres causes. Il s’agit de critères de décision clinique, pas d’un diagnostic posé par un questionnaire.')),
('Les {examens précisent mécanisme et gravité}. La polygraphie ambulatoire convient à des situations sélectionnées. Une polysomnographie est utile devant résultat incertain ou symptômes persistants.',paras('La polygraphie suisse comporte notamment débit, effort, saturation et position ; le document de référence indique au moins quatre heures exploitables avec les signaux essentiels. La polysomnographie en centre spécialisé ajoute l’analyse du sommeil.', 'Une oxymétrie négative ne suffit pas à exclure une maladie. Si une hypoventilation est suspectée, compléter par gaz sanguins à l’éveil et mesure nocturne du dioxyde de carbone selon indication. Aucun examen ne doit retarder le traitement d’une insuffisance ventilatoire aiguë.')),
('L’{algorithme associe confirmation et réduction du risque}. Traiter d’abord une situation instable. Choisir ensuite une intervention dont l’efficacité sera vérifiée.',steps('Sécuriser conduite, poste de travail et respiration selon les signes.', 'Confirmer le trouble par un enregistrement adapté et une lecture clinique.', 'Rechercher facteurs aggravants et mécanismes associés.', 'Proposer pression positive, orthèse ou autre option selon indication et préférence éclairée.', 'Contrôler utilisation, tolérance, symptômes et événements résiduels ; adapter si réponse insuffisante.')),
('La {prise en charge suisse repose souvent sur la pression positive continue}. La réduction pondérale et les mesures de sommeil l’accompagnent. Une orthèse est possible dans certaines situations après bilan dentaire.',paras('La pression positive maintient la perméabilité pharyngée ; réglage, masque et accompagnement sont individualisés par l’équipe du sommeil. Ne pas remplacer un traitement indiqué par une attente de perte de poids.', 'Selon la SSSSC, une orthèse peut être utilisée dans des formes légères ou modérées sélectionnées, ou après essai infructueux de pression positive dans une forme sévère. NICE la positionne principalement après intolérance ou refus : la différence est explicitée, sans transformer la recommandation britannique en obligation suisse.', 'Une thérapie positionnelle requiert un caractère positionnel documenté ; chirurgie ou stimulation du nerf hypoglosse concernent des patients sélectionnés. Aucun médicament n’est prescrit ici comme traitement universel des apnées. Les causes nasales ou endocriniennes se traitent pour leur indication propre.')),
('Le {suivi vérifie bénéfice et utilisation réelle}. La baisse du ronflement ne suffit pas. Une gêne de masque ou une rhinite doit être traitée tôt pour éviter l’abandon.',paras('Le référentiel suisse prévoit un contrôle médical à trois mois au plus tard et aussi souvent que nécessaire pendant l’adaptation ; NICE propose un premier contact dans le mois. Réévaluer fuites, sécheresse, durée d’utilisation, données de l’appareil et vigilance.', 'La réduction de somnolence et l’amélioration de qualité de vie sont des objectifs établis. La prévention cardiovasculaire individuelle ne peut pas être garantie. Un changement important de poids ou des symptômes résiduels peut justifier un nouvel enregistrement.')),
('Le {point clé est de relier physiologie, symptômes et sécurité}. Un score rassurant ou une morphologie mince n’exclut pas la maladie. Le traitement reste évalué sur plusieurs dimensions.',paras('La suppression des événements respiratoires ne corrige pas automatiquement toute fatigue. À l’inverse, une amélioration subjective ne prouve pas la normalisation respiratoire.', 'La conduite et les professions de sécurité demandent un avis adapté au cadre suisse. Ne pas annoncer une aptitude sur le seul fait que le patient possède un appareil.'))]
quiz=[('Le ronflement seul suffit-il au diagnostic ?','Non.'),('Les efforts respiratoires persistent-ils dans une apnée obstructive ?','Oui, contrairement au mécanisme central pur.'),('Une personne mince peut-elle être atteinte ?','Oui.'),('Epworth normal exclut-il le trouble ?','Non.'),('Quel risque impose une action immédiate concernant la conduite ?','Un endormissement ou une somnolence dangereuse : cesser de conduire et consulter rapidement.'),('L’oxymétrie seule exclut-elle les apnées ?','Non.'),('Une polygraphie négative malgré symptômes persistants peut-elle conduire à une polysomnographie ?','Oui.'),('L’indice horaire suffit-il à juger la gravité ?','Non, considérer désaturations, symptômes et comorbidités.'),('Faut-il attendre une perte de poids pour traiter une forme sévère ?','Non.'),('Une orthèse exige-t-elle une évaluation dentaire ?','Oui.'),('Toute apnée répond-elle au même dispositif ?','Non, les mécanismes centraux ou l’hypoventilation nécessitent une évaluation spécifique.'),('Le traitement garantit-il la prévention d’un événement cardiovasculaire ?','Non.'),('Un appareil acquis prouve-t-il une utilisation efficace ?','Non.'),('Une somnolence résiduelle justifie-t-elle une nouvelle analyse ?','Oui, respiratoire et non respiratoire.')]
produire(1,parts,quiz,(1,3,4,7,23))
